from pathlib import Path

def replace_once(path, old, new, label):
    p = Path(path)
    if not p.exists():
        raise SystemExit(f"ERROR: Missing {path}")
    s = p.read_text(encoding="utf-8")
    n = s.count(old)
    if n != 1:
        raise SystemExit(f"ERROR: {label}: expected 1 match, found {n}")
    p.write_text(s.replace(old, new, 1), encoding="utf-8")

old_stripe = 'export async function cancelPendingContributionOnStripe(contributionId: string) {\n  const admin = createAdminClient();\n  const stripe = stripeClient();\n\n  const { data: contribution, error } = await admin\n    .from("support_contributions")\n    .select("id, status, stripe_environment, stripe_checkout_session_id")\n    .eq("id", contributionId)\n    .single();\n\n  if (error || !contribution) {\n    throw new Error(error?.message ?? "Contribution not found.");\n  }\n\n  if (contribution.status !== "pending") {\n    throw new Error("Only pending contributions can be cancelled.");\n  }\n\n  assertContributionEnvironment(contribution.stripe_environment);\n\n  const sessionId = contribution.stripe_checkout_session_id?.trim() ?? "";\n\n  if (sessionId) {\n    const session = await stripe.checkout.sessions.retrieve(sessionId);\n\n    if (session.payment_status === "paid") {\n      throw new Error(\n        "Stripe reports this contribution as paid. Refresh/reconcile it before attempting a refund.",\n      );\n    }\n\n    if (session.status === "open") {\n      await stripe.checkout.sessions.expire(sessionId);\n    } else if (session.status === "complete") {\n      throw new Error(\n        "This Checkout Session is already complete and cannot be cancelled.",\n      );\n    }\n  }\n\n  const { error: updateError } = await admin\n    .from("support_contributions")\n    .update({\n      status: "failed",\n      updated_at: new Date().toISOString(),\n    })\n    .eq("id", contribution.id)\n    .eq("status", "pending");\n\n  if (updateError) throw new Error(updateError.message);\n\n  return { cancelled: true };\n}\n'
new_stripe = 'export async function cancelPendingContributionOnStripe(contributionId: string) {\n  const admin = createAdminClient();\n  const stripe = stripeClient();\n\n  const { data: contribution, error } = await admin\n    .from("support_contributions")\n    .select(\n      "id, status, amount_minor, stripe_environment, stripe_checkout_session_id, stripe_payment_intent_id, stripe_charge_id",\n    )\n    .eq("id", contributionId)\n    .single();\n\n  if (error || !contribution) {\n    throw new Error(error?.message ?? "Contribution not found.");\n  }\n\n  if (contribution.status !== "pending") {\n    throw new Error("Only pending contributions can be checked or cancelled.");\n  }\n\n  assertContributionEnvironment(contribution.stripe_environment);\n\n  const sessionId = contribution.stripe_checkout_session_id?.trim() ?? "";\n\n  if (!sessionId) {\n    const { error: updateError } = await admin\n      .from("support_contributions")\n      .update({\n        status: "failed",\n        updated_at: new Date().toISOString(),\n      })\n      .eq("id", contribution.id)\n      .eq("status", "pending");\n\n    if (updateError) throw new Error(updateError.message);\n    return { result: "cancelled" as const };\n  }\n\n  const session = await stripe.checkout.sessions.retrieve(sessionId, {\n    expand: ["payment_intent"],\n  });\n\n  if (session.payment_status === "paid") {\n    const paymentIntent =\n      session.payment_intent &&\n      typeof session.payment_intent !== "string"\n        ? session.payment_intent\n        : null;\n\n    const paymentIntentId =\n      typeof session.payment_intent === "string"\n        ? session.payment_intent\n        : paymentIntent?.id ??\n          contribution.stripe_payment_intent_id ??\n          null;\n\n    const latestCharge = paymentIntent?.latest_charge;\n\n    const chargeId =\n      typeof latestCharge === "string"\n        ? latestCharge\n        : latestCharge?.id ??\n          contribution.stripe_charge_id ??\n          null;\n\n    const amountMinor =\n      typeof session.amount_total === "number"\n        ? session.amount_total\n        : Number(contribution.amount_minor);\n\n    const now = new Date().toISOString();\n\n    const { error: reconcileError } = await admin\n      .from("support_contributions")\n      .update({\n        status: "paid",\n        amount_minor: amountMinor,\n        stripe_payment_intent_id: paymentIntentId,\n        stripe_charge_id: chargeId,\n        stripe_customer_id:\n          typeof session.customer === "string"\n            ? session.customer\n            : session.customer?.id ?? null,\n        paid_at: now,\n        updated_at: now,\n      })\n      .eq("id", contribution.id)\n      .eq("status", "pending");\n\n    if (reconcileError) throw new Error(reconcileError.message);\n    return { result: "reconciled_paid" as const };\n  }\n\n  if (session.status === "open") {\n    await stripe.checkout.sessions.expire(sessionId);\n  } else if (session.status === "complete") {\n    throw new Error(\n      "This Checkout Session is complete but Stripe has not marked it paid. Check the Stripe payment before changing this record.",\n    );\n  }\n\n  const { error: updateError } = await admin\n    .from("support_contributions")\n    .update({\n      status: "failed",\n      updated_at: new Date().toISOString(),\n    })\n    .eq("id", contribution.id)\n    .eq("status", "pending");\n\n  if (updateError) throw new Error(updateError.message);\n  return { result: "cancelled" as const };\n}\n'
replace_once("lib/contributions/stripe-server.ts", old_stripe, new_stripe, "stripe pending reconciliation")

p = Path("app/(portal)/admin/contributions/actions.ts")
s = p.read_text(encoding="utf-8")
imp = 'import {\n  cancelPendingContributionOnStripe,\n  refundContributionOnStripe,\n  syncContributionProductToStripe,\n} from "@/lib/contributions/stripe-server";\n'
if "sendContributionThankYouEmail" not in s:
    if s.count(imp) != 1:
        raise SystemExit("ERROR: admin import anchor not found")
    s = s.replace(imp, imp + 'import { sendContributionThankYouEmail } from "@/lib/contributions/contribution-email";\n', 1)
old_action = 'export async function cancelPendingContribution(fd: FormData) {\n  await auth();\n  const id = read(fd, "id");\n  if (!id) throw new Error("Contribution ID is required.");\n  await cancelPendingContributionOnStripe(id);\n  refresh();\n}\n'
new_action = 'export async function cancelPendingContribution(fd: FormData) {\n  await auth();\n\n  const id = read(fd, "id");\n  if (!id) throw new Error("Contribution ID is required.");\n\n  const result = await cancelPendingContributionOnStripe(id);\n\n  if (result.result === "reconciled_paid") {\n    try {\n      await sendContributionThankYouEmail(id);\n    } catch (emailError) {\n      console.error(\n        "Contribution was reconciled as paid from admin, but the thank-you email failed:",\n        emailError,\n      );\n    }\n  }\n\n  refresh();\n  return result;\n}\n'
if s.count(old_action) != 1:
    raise SystemExit("ERROR: admin cancel action not found")
s = s.replace(old_action, new_action, 1)
p.write_text(s, encoding="utf-8")

old_feedback = '                                action={cancelPendingContribution}\n                                successMessage="Pending contribution cancelled."\n                                pendingLabel="Cancelling..."\n'
new_feedback = '                                action={cancelPendingContribution}\n                                successMessage="Contribution checked against Stripe and updated."\n                                pendingLabel="Checking..."\n'
replace_once("app/(portal)/admin/contributions/page.tsx", old_feedback, new_feedback, "admin pending button feedback")

